# alf_world_state_tracker
# Tracks held objects, current location and receptacles seen empty from
# step observations, and restates the task line each step. No answer
# coaching: it only reports what the trajectory itself has shown.

TASK_MARK = "Your task is to:"

def applies(view):
    return TASK_MARK in view.get("initial_observation", "")


def _task_line(view):
    text = view.get("initial_observation", "")
    idx = text.find(TASK_MARK)
    if idx < 0:
        return None
    line = text[idx + len(TASK_MARK):].strip()
    return line[:190] if line else None


def alf_after_step(event, state):
    obs = event.get("observation", "") or ""
    step = event.get("step", 0)
    st = state if isinstance(state, dict) else {}
    held = list(st.get("held", []))
    empty = list(st.get("empty", []))
    location = st.get("location")

    if obs.startswith("You arrive at "):
        rest = obs[len("You arrive at "):].split(".", 1)[0]
        location = rest.strip()[:80]
        if ", you see nothing" in obs or "you see nothing." in obs:
            if location and location not in empty:
                empty.append(location)

    if obs.startswith("You pick up the "):
        rest = obs[len("You pick up the "):].split(" from ", 1)[0]
        item = rest.strip()[:80]
        if item and item not in held:
            held.append(item)

    if obs.startswith("You put the "):
        rest = obs[len("You put the "):].split(" in/on ", 1)[0]
        item = rest.strip()[:80]
        if item in held:
            held.remove(item)

    return {"held": held, "empty": empty, "location": location, "step": step}


def alf_before_step(view, state):
    facts = []
    warnings = []
    st = state if isinstance(state, dict) else {}

    task = _task_line(view)
    if task:
        facts.append("Task: " + task)

    held = st.get("held") or []
    if held:
        facts.append("Held: " + ", ".join(held))
    else:
        facts.append("Held: nothing")

    location = st.get("location")
    if location:
        facts.append("At: " + location)

    empty = st.get("empty") or []
    if empty:
        facts.append("Seen empty: " + ", ".join(empty[-4:]))

    obs = view.get("observation", "") or ""
    if obs.strip() == "Nothing happens.":
        warnings.append("Previous action had no effect; try a different admissible command.")

    return {"fields": {"facts": facts, "warnings": warnings}, "discourage": []}
