# alf_command_guard
# Before each step, discourage candidate actions that are not present
# verbatim in the current admissible_commands, and discourage repeating
# an action whose most recent observation was "Nothing happens."

def alf_before_step(view, state):
    admissible = list(view.get("admissible_commands") or [])
    admissible_set = set(admissible)
    history = list(view.get("recent_history") or [])
    facts = []
    warnings = []
    discourage = []

    if admissible:
        for cmd in admissible:
            if cmd not in admissible_set:
                discourage.append(cmd)

    # Find any proposed action: this hook sees the view, not the reply,
    # so we guard the last action if it failed and is still listed.
    last_action = None
    last_obs = None
    if history:
        last = history[-1] if isinstance(history[-1], dict) else {}
        last_action = (last.get("action") or "")[:118]
        last_obs = (last.get("observation") or "").strip()

    if last_action and last_obs == "Nothing happens.":
        discourage.append(last_action)
        warnings.append(
            "Last action '" + last_action + "' had no effect; avoid repeating it."
        )

    obs = (view.get("observation") or "").strip()
    if obs == "Nothing happens." and last_action and last_action not in discourage:
        discourage.append(last_action)
        warnings.append("Previous action did nothing; choose a different command.")

    if not discourage:
        return {"fields": {}, "discourage": []}

    return {
        "fields": {"warnings": warnings[:3]},
        "discourage": discourage[:10],
    }
